static int16_t closest_angles_index(double angles)
{
    int16_t left = 0, mid = 0, right = CAL_NUM - 1;

    while (left <= right) {
        mid = (left + right) >> 1;
        if (cal_angles[mid] == angles)
            return mid;
        else if (cal_angles[mid] < angles)
            left = mid + 1;
        else
            right = mid - 1;
    }
 //   if (left > CAL_NUM || right < 0)
 //       return CAL_NUM - 1; //both select scal_values 0
 //   else
        return ((cal_angles[left] - angles) < (angles - cal_angles[right])) ? left : right;
}

static double calib_aoa_linear(double current_aoa)
{
    double aoa_caled = 0; double cal = 0; int index = 0;

    if (current_aoa > cal_angles[CAL_NUM-1] && cal_angles[CAL_NUM-1] != 0)
        aoa_caled = 180;
    else if (current_aoa < cal_angles[0])
        aoa_caled = -180;
    else
    {
        index = closest_angles_index(current_aoa);
        cal   = cal_values[index];
        aoa_caled = current_aoa - cal;
    }
    if (aoa_caled > 180)
        aoa_caled = 180;
    else if (aoa_caled < -180)
        aoa_caled = -180;

    //uart2_printf(" %f, %d, %f, %f",current_aoa,index,cal,aoa_caled);
    return aoa_caled;
}

/**
 *  Calibration DIS Algorithm
 */
 typedef struct {
    float d;
    float v;
    float P[2][2];
    float Q[2];
    float R;
    float dt;
} KF_TWR_t;

/* One independent Kalman state per anchor (src index) so ranges of
 * different anchors do not pollute each other. */
static KF_TWR_t kf_twr[MAX_ANCHOR_LIST_SIZE];

void kf_twr_init(float dt) {
    for (uint8_t src = 0; src < MAX_ANCHOR_LIST_SIZE; src++) {
        KF_TWR_t *kf = &kf_twr[src];

        kf->d = 0.0f;
        kf->v = 0.0f;
        kf->dt = dt;

        kf->P[0][0] = 1.0f;
        kf->P[0][1] = 0.0f;
        kf->P[1][0] = 0.0f;
        kf->P[1][1] = 1.0f;

        kf->Q[0] = 0.001f;
        kf->Q[1] = 0.01f;
        kf->R    = 0.005f;
    }
}

static void kf_twr_predict(KF_TWR_t *kf) {
    float dt = kf->dt;

    // 状态预测
    float pred_d = kf->d + kf->v * dt;
    float pred_v = kf->v;

    // 协方差预测
    float p00 = kf->P[0][0];
    float p01 = kf->P[0][1];
    float p10 = kf->P[1][0];
    float p11 = kf->P[1][1];

    kf->P[0][0] = p00 + dt * p10 + dt * (p01 + dt * p11) + kf->Q[0];
    kf->P[0][1] = p01 + dt * p11;
    kf->P[1][0] = p10 + dt * p11;
    kf->P[1][1] = p11 + kf->Q[1];

    kf->d = pred_d;
    kf->v = pred_v;
}

float kf_twr_update(uint8_t src, float meas_d) {
    if (src >= MAX_ANCHOR_LIST_SIZE) return meas_d; //out of range: return raw measurement

    KF_TWR_t *kf = &kf_twr[src];
    kf_twr_predict(kf);

    // 卡尔曼增益
    float S = kf->P[0][0] + kf->R;
    float K0 = kf->P[0][0] / S;
    float K1 = kf->P[1][0] / S;

    // 残差
    float y = meas_d - kf->d;

    // 状态更新
    kf->d += K0 * y;
    kf->v += K1 * y;

    // 协方差更新
    float p00 = kf->P[0][0];
    float p01 = kf->P[0][1];

    kf->P[0][0] -= K0 * p00;
    kf->P[0][1] -= K0 * p01;
    kf->P[1][0] -= K1 * p00;
    kf->P[1][1] -= K1 * p01;

    return kf->d;
}

